sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var sessionId = 'atf_e2e_' + new GlideDateTime().getNumericValue();

    // --- Call ClaudeConnector ---
    var connector = new x_146833_claudec_0.ClaudeConnector();
    var messages = [{ role: 'user', content: 'Reply with exactly: Hello from Claude' }];
    var opts = {
        model: 'claude-sonnet-5',
        session_id: sessionId,
        prompt: 'Reply with exactly: Hello from Claude'
    };

    var result = connector.chatWithTools(messages, opts);

    // Verify the connector returned success
    assertEqual({ name: 'API call succeeded', shouldbe: true, value: result.success === true });
    assertEqual({ name: 'Response has text',  shouldbe: true, value: (result.text || '').length > 0 });
    assertEqual({ name: 'Input tokens > 0',   shouldbe: true, value: (result.inputTokens || 0) > 0 });
    assertEqual({ name: 'Output tokens > 0',  shouldbe: true, value: (result.outputTokens || 0) > 0 });
    assertEqual({ name: 'Model returned',     shouldbe: true, value: (result.model || '').length > 0 });

    // --- Verify the staging table record ---
    var gr = new GlideRecord('x_146833_claudec_0_request');
    gr.addQuery('session_id', sessionId);
    gr.orderByDesc('sys_created_on');
    gr.setLimit(1);
    gr.query();

    assertEqual({ name: 'Staging record exists', shouldbe: true, value: gr.next() });

    var status       = gr.getValue('status') || '';
    var model        = gr.getValue('model') || '';
    var inputTokens  = parseInt(gr.getValue('input_tokens'), 10) || 0;
    var outputTokens = parseInt(gr.getValue('output_tokens'), 10) || 0;
    var durationMs   = parseInt(gr.getValue('duration_ms'), 10) || 0;
    var prompt       = gr.getValue('prompt') || '';
    var responseText = gr.getValue('response_text') || '';

    assertEqual({ name: 'Staging: status=success',       shouldbe: 'success', value: status });
    assertEqual({ name: 'Staging: model populated',       shouldbe: true,      value: model.length > 0 });
    assertEqual({ name: 'Staging: input_tokens > 0',      shouldbe: true,      value: inputTokens > 0 });
    assertEqual({ name: 'Staging: output_tokens > 0',     shouldbe: true,      value: outputTokens > 0 });
    assertEqual({ name: 'Staging: duration_ms > 0',       shouldbe: true,      value: durationMs > 0 });
    assertEqual({ name: 'Staging: prompt captured',       shouldbe: true,      value: prompt.length > 0 });
    assertEqual({ name: 'Staging: response_text captured', shouldbe: true,     value: responseText.length > 0 });

    stepResult.setOutputMessage(
        'PASS — Claude responded and staging record verified.\n' +
        '  Response: ' + (result.text || '').substring(0, 100) + '\n' +
        '  Model: ' + result.model + '\n' +
        '  Tokens: in=' + result.inputTokens + ' out=' + result.outputTokens + '\n' +
        '  Staging record sys_id=' + gr.getUniqueValue() +
        ', status=' + status +
        ', duration_ms=' + durationMs
    );
})(outputs, steps, params, stepResult, assertEqual);
